create extension if not exists pgcrypto;
create table public.faculties(id uuid primary key default gen_random_uuid(),name text not null unique,created_at timestamptz not null default now());
create table public.departments(id uuid primary key default gen_random_uuid(),faculty_id uuid not null references public.faculties(id) on delete cascade,name text not null,created_at timestamptz not null default now(),unique(faculty_id,name));
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null unique,full_name text not null,faculty_id uuid references public.faculties(id),department_id uuid references public.departments(id),level text,gender text,bio text,avatar_url text,is_visible boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.interests(id uuid primary key default gen_random_uuid(),name text not null unique);create table public.user_interests(user_id uuid references public.profiles(id) on delete cascade,interest_id uuid references public.interests(id) on delete cascade,primary key(user_id,interest_id));
create type public.connection_status as enum('pending','accepted','declined','blocked');create table public.connections(id uuid primary key default gen_random_uuid(),requester_id uuid not null references public.profiles(id) on delete cascade,recipient_id uuid not null references public.profiles(id) on delete cascade,status public.connection_status not null default 'pending',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(requester_id<>recipient_id),unique(requester_id,recipient_id));
create table public.matches(id uuid primary key default gen_random_uuid(),user_a_id uuid not null references public.profiles(id) on delete cascade,user_b_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),unique(user_a_id,user_b_id),check(user_a_id<>user_b_id));
create table public.conversations(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now());create table public.conversation_members(conversation_id uuid references public.conversations(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,joined_at timestamptz not null default now(),primary key(conversation_id,user_id));create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,content text not null check(length(trim(content))>0 and length(content)<=5000),created_at timestamptz not null default now());
create table public.communities(id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.profiles(id),name text not null,description text,category text,created_at timestamptz not null default now());create table public.community_members(community_id uuid references public.communities(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,joined_at timestamptz not null default now(),primary key(community_id,user_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,type text not null,payload jsonb not null default '{}',read_at timestamptz,created_at timestamptz not null default now());create table public.blocks(blocker_id uuid references public.profiles(id) on delete cascade,blocked_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id),reported_user_id uuid references public.profiles(id),message_id uuid references public.messages(id),reason text not null,details text,created_at timestamptz not null default now());create table public.user_preferences(user_id uuid primary key references public.profiles(id) on delete cascade,profile_visible boolean not null default true,allow_messages text not null default 'connections',allow_requests boolean not null default true,show_online boolean not null default true,notifications_enabled boolean not null default true);create table public.chat_preferences(user_id uuid primary key references public.profiles(id) on delete cascade,theme text not null default 'default');
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,username,full_name) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'username',''),'user_'||substr(new.id::text,1,8)),coalesce(nullif(new.raw_user_meta_data->>'full_name',''),'New student'));insert into public.user_preferences(user_id) values(new.id);insert into public.chat_preferences(user_id) values(new.id);return new;end;$$;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;alter table public.user_interests enable row level security;alter table public.connections enable row level security;alter table public.matches enable row level security;alter table public.conversations enable row level security;alter table public.conversation_members enable row level security;alter table public.messages enable row level security;alter table public.communities enable row level security;alter table public.community_members enable row level security;alter table public.notifications enable row level security;alter table public.blocks enable row level security;alter table public.reports enable row level security;alter table public.user_preferences enable row level security;alter table public.chat_preferences enable row level security;
create policy "visible profiles readable" on public.profiles for select using(is_visible=true or id=auth.uid());create policy "own profile update" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());create policy "own interests" on public.user_interests for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "connection participants" on public.connections for select using(requester_id=auth.uid() or recipient_id=auth.uid());create policy "create own request" on public.connections for insert with check(requester_id=auth.uid());create policy "update connection" on public.connections for update using(requester_id=auth.uid() or recipient_id=auth.uid());create policy "match participants" on public.matches for select using(user_a_id=auth.uid() or user_b_id=auth.uid());create policy "conversation members" on public.conversation_members for select using(user_id=auth.uid());create policy "join own conversation" on public.conversation_members for insert with check(user_id=auth.uid());create policy "member messages read" on public.messages for select using(exists(select 1 from public.conversation_members cm where cm.conversation_id=messages.conversation_id and cm.user_id=auth.uid()));create policy "send own messages" on public.messages for insert with check(sender_id=auth.uid() and exists(select 1 from public.conversation_members cm where cm.conversation_id=messages.conversation_id and cm.user_id=auth.uid()));create policy "own notifications" on public.notifications for select using(user_id=auth.uid());create policy "own notification update" on public.notifications for update using(user_id=auth.uid());create policy "own block management" on public.blocks for all using(blocker_id=auth.uid()) with check(blocker_id=auth.uid());create policy "own reports" on public.reports for insert with check(reporter_id=auth.uid());create policy "own preferences" on public.user_preferences for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "own chat preferences" on public.chat_preferences for all using(user_id=auth.uid()) with check(user_id=auth.uid());